function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function getString(value) {
  return String(value || "").trim();
}

function getNumber(value) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function formatDate(value) {
  if (!value) return "-";

  try {
    return new Date(value).toLocaleDateString("tr-TR", {
      day: "2-digit",
      month: "long",
      year: "numeric",
    });
  } catch {
    return value;
  }
}

function sortGradeType(type) {
  const order = {
    Vize: 1,
    Laboratuvar: 2,
    Final: 3,
    Ortalama: 4,
  };

  return order[type] || 99;
}

function buildGradeListHtml(grades) {
  const rows = grades
    .sort((a, b) => sortGradeType(a.type) - sortGradeType(b.type))
    .map((grade) => {
      return `
<tr>
  <td style="padding:12px;border-bottom:1px solid #e2e8f0;color:#0f172a;font-weight:700;">
    ${grade.type}
  </td>
  <td style="padding:12px;border-bottom:1px solid #e2e8f0;color:#0f172a;">
    ${grade.score}/${grade.maxPoint || 100}
  </td>
  <td style="padding:12px;border-bottom:1px solid #e2e8f0;color:#64748b;">
    ${formatDate(grade.publishDate || grade.date)}
  </td>
</tr>`;
    })
    .join("");

  return `
<table style="width:100%;border-collapse:collapse;margin-top:14px;border:1px solid #e2e8f0;border-radius:14px;overflow:hidden;">
  <thead>
    <tr style="background:#f8fafc;">
      <th style="padding:12px;text-align:left;color:#475569;font-size:12px;text-transform:uppercase;letter-spacing:1px;">Not Türü</th>
      <th style="padding:12px;text-align:left;color:#475569;font-size:12px;text-transform:uppercase;letter-spacing:1px;">Puan</th>
      <th style="padding:12px;text-align:left;color:#475569;font-size:12px;text-transform:uppercase;letter-spacing:1px;">Yayın Tarihi</th>
    </tr>
  </thead>
  <tbody>
    ${rows}
  </tbody>
</table>`;
}

function buildEmailHtml({
  studentName,
  className,
  grades,
  trackingCodesText,
}) {
  const averageGrade = grades.find((grade) => grade.type === "Ortalama");
  const averageText = averageGrade
    ? `${averageGrade.score}/${averageGrade.maxPoint || 100}`
    : "Henüz hesaplanmadı";

  return `
<div style="font-family:Arial,Helvetica,sans-serif;background:#f1f5f9;padding:32px;">
  <div style="max-width:680px;margin:auto;background:white;border-radius:24px;overflow:hidden;border:1px solid #e2e8f0;">
    <div style="background:#0f172a;color:white;padding:28px 32px;">
      <div style="font-size:12px;letter-spacing:4px;text-transform:uppercase;color:#bfdbfe;font-weight:700;">
        AkıllıSınıf AI
      </div>
      <h1 style="margin:12px 0 0;font-size:28px;line-height:1.2;color:#ffffff;">
        Yeni Notlar Yayında
      </h1>
      <p style="margin:12px 0 0;color:#dbeafe;font-size:15px;line-height:1.6;">
        Bu bildirim, öğretmeniniz notları ilan ettikten sonra otomatik oluşturulmuştur.
      </p>
    </div>

    <div style="padding:32px;color:#0f172a;">
      <p style="margin:0 0 16px;font-size:16px;line-height:1.7;">
        Merhaba <strong>${studentName}</strong>,
      </p>

      <p style="margin:0 0 20px;font-size:16px;line-height:1.7;">
        <strong>${className}</strong> sınıfı için yeni notlarınız yayınlandı.
      </p>

      <div style="margin:22px 0;padding:18px;border-radius:18px;background:#eff6ff;border:1px solid #bfdbfe;">
        <p style="margin:0;color:#1d4ed8;font-size:12px;text-transform:uppercase;font-weight:700;letter-spacing:1px;">
          Ortalama
        </p>
        <p style="margin:8px 0 0;font-size:26px;font-weight:800;color:#1e3a8a;">
          ${averageText}
        </p>
      </div>

      ${buildGradeListHtml(grades)}

      <p style="margin:22px 0 0;font-size:15px;line-height:1.7;color:#475569;">
        Notlarınızı AkıllıSınıf AI öğrenci panelinizden de inceleyebilirsiniz.
      </p>

      <div style="margin-top:28px;padding:16px;border-radius:16px;background:#f8fafc;border:1px solid #e2e8f0;color:#64748b;font-size:12px;line-height:1.6;">
        Sistem takip kodları:<br/>
        ${trackingCodesText}
      </div>
    </div>

    <div style="background:#f8fafc;padding:20px 32px;border-top:1px solid #e2e8f0;color:#64748b;font-size:12px;line-height:1.6;">
      AkıllıSınıf AI · Yapay Zekâ Destekli Sınıf Performans ve Erken Uyarı Sistemi
    </div>
  </div>
</div>
`;
}

const grades = getRecords("GET Published Grades");
const users = getRecords("GET Users");
const classes = getRecords("GET Classes");
const existingNotifications = getRecords("GET Existing Grade Notifications");

const existingMessages = existingNotifications
  .map((notification) => getString(notification.fields.Mesaj))
  .join("\n");

const groups = new Map();

for (const grade of grades) {
  const studentId = asLinks(grade.fields.Ogrenci)[0];
  const classId = asLinks(grade.fields.Sinif)[0];

  if (!studentId || !classId) continue;

  const type = getString(grade.fields.Not_Turu);
  const score = getNumber(grade.fields.Puan);
  const maxPoint = getNumber(grade.fields.Maksimum_Puan) || 100;

  if (!type || score === null) continue;

  const trackingCode = `NOT:${grade.id}:ALICI:${studentId}`;

  if (existingMessages.includes(trackingCode)) {
    continue;
  }

  const student = users.find((user) => user.id === studentId);
  const classRecord = classes.find((item) => item.id === classId);

  const studentName = getString(student?.fields?.Ad_Soyad) || "Öğrenci";
  const studentEmail = getString(student?.fields?.Eposta);
  const className =
    getString(classRecord?.fields?.Sinif_Adi) ||
    getString(classRecord?.fields?.Ders_Adi) ||
    "Sınıf";

  if (!studentEmail) continue;

  const groupKey = `${studentId}:${classId}`;

  if (!groups.has(groupKey)) {
    groups.set(groupKey, {
      studentId,
      classId,
      studentName,
      studentEmail,
      className,
      grades: [],
      trackingCodes: [],
    });
  }

  const group = groups.get(groupKey);

  group.grades.push({
    id: grade.id,
    type,
    score,
    maxPoint,
    date: getString(grade.fields.Tarih),
    publishDate: getString(grade.fields.Yayin_Tarihi),
    trackingCode,
  });

  group.trackingCodes.push(trackingCode);
}

const output = [];

for (const group of groups.values()) {
  if (group.grades.length === 0) continue;

  const gradeSummaryText = group.grades
    .sort((a, b) => sortGradeType(a.type) - sortGradeType(b.type))
    .map((grade) => `${grade.type}: ${grade.score}/${grade.maxPoint || 100}`)
    .join(", ");

  const trackingCodesText = group.trackingCodes.join("<br/>");
  const trackingCodesPlain = group.trackingCodes.join("\n");

  const message =
    `Merhaba ${group.studentName}, ${group.className} sınıfı için yeni notlarınız yayınlandı. ` +
    `Yayınlanan notlar: ${gradeSummaryText}.\n\n` +
    `Sistem takip kodları:\n${trackingCodesPlain}`;

  const emailSubject = `Yeni notlar yayınlandı: ${group.className}`;

  const emailHtml = buildEmailHtml({
    studentName: group.studentName,
    className: group.className,
    grades: group.grades,
    trackingCodesText,
  });

  output.push({
    json: {
      emailTo: group.studentEmail,
      emailSubject,
      emailHtml,
      studentName: group.studentName,
      className: group.className,
      gradeSummaryText,
      trackingCodesPlain,
      fields: {
        Bildirim_Basligi: "Not ilan edildi",
        Alici: [group.studentId],
        Sinif: [group.classId],
        Bildirim_Turu: "Not Bildirimi",
        Mesaj: message,
        Onem_Derecesi: "Orta",
        Okundu_Mu: false,
        Gonderildi_Mi: true,
        Kanal: "E-posta + Webhook",
      },
    },
  });
}

return output;
